$ErrorActionPreference='Stop';$results=@()
function Tool-Fixture([string]$arguments){$i=New-Object Diagnostics.ProcessStartInfo;$i.FileName=$global:MediaDir+'\tools\ffmpeg.exe';$i.Arguments=$arguments;$i.UseShellExecute=$false;$i.CreateNoWindow=$true;$p=[Diagnostics.Process]::Start($i);if(-not$p.WaitForExit(10000)){$p.Kill();throw 'Fixture generator timeout'};if($p.ExitCode-ne0){throw 'Fixture generator failed'};$p.Dispose()}
Tool-Fixture ('-v error -nostdin -y -f lavfi -i anullsrc=r=16000:cl=mono -t 1 "'+$global:MediaDir+'\silent.wav"')
Tool-Fixture ('-v error -nostdin -y -f lavfi -i color=c=black:s=32x32:d=1 -an -c:v mpeg4 "'+$global:MediaDir+'\no-audio.mp4"')
$clipboardBefore=[Windows.Forms.Clipboard]::GetText();$last=(Get-FileHash ($env:APPDATA+'\DybergCo\Koett\data\Last Transcript.txt')).Hash
foreach($case in @(@('silent.wav','No speech'),@('no-audio.mp4','audio'))){Media-Source ($global:MediaDir+'\'+$case[0]);Media-Invoke '1';$null=Wait-MediaDone;$message=(Media-Item '108').Current.Name;$results+=@{name=$case[0];passed=($message-match$case[1]);message=$message;focus=Get-LabFocus}}
$tool=$global:MediaDir+'\tools\ffprobe.exe';$backup=$tool+'.m5-disabled';if(Test-Path $backup){throw 'Tool backup exists'}
try{Move-Item $tool $backup;Media-Source ($global:MediaDir+'\silent.wav');Media-Invoke '1';$null=Wait-MediaDone;$message=(Media-Item '108').Current.Name;$results+=@{name='missing-ffprobe';passed=($message-match'ffprobe');message=$message;focus=Get-LabFocus}}finally{Move-Item $backup $tool}
Media-Source 'http://10.0.2.2:18768/slow.wav';Media-Invoke '1'
$watch=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 100;$pill=[Windows.Automation.AutomationElement]::FromHandle([LabDriver]::ByClass('KoettOverlayWindow'));$cancel=$pill.FindFirst([Windows.Automation.TreeScope]::Children,(New-Object Windows.Automation.PropertyCondition([Windows.Automation.AutomationElement]::NameProperty,'Cancel')))}while(-not$cancel-and$watch.ElapsedMilliseconds-lt5000)
if(-not$cancel){throw 'Media pill Cancel missing'};$before=Get-LabFocus;([Windows.Automation.InvokePattern]$cancel.GetCurrentPattern([Windows.Automation.InvokePattern]::Pattern)).Invoke();$null=Wait-MediaDone;$after=Get-LabFocus;$message=(Media-Item '108').Current.Name
$results+=@{name='pill-cancel-slow-fetch';passed=($message-match'cancel'-and$before.hwnd-eq$after.hwnd-and$before.pid-eq$after.pid);message=$message;before=$before;after=$after}
$clipAfter=[Windows.Forms.Clipboard]::GetText();$lastAfter=(Get-FileHash ($env:APPDATA+'\DybergCo\Koett\data\Last Transcript.txt')).Hash;$tools=@(Get-Process ffprobe,ffmpeg,yt-dlp -ErrorAction SilentlyContinue|Select-Object Id,ProcessName)
@{passed=(@($results|Where-Object {-not$_.passed}).Count-eq0-and$clipAfter-ceq$clipboardBefore-and$last-eq$lastAfter-and$tools.Count-eq0);results=$results;clipboard_unchanged=($clipAfter-ceq$clipboardBefore);dictation_last_unchanged=($last-eq$lastAfter);orphan_tools=$tools;artifact=Get-LabArtifact;step=Media-Step 'media-cancelled'}
